const fs=require('node:fs'),path=require('node:path'),assert=require('node:assert/strict');
const sharp=require(process.env.YAMB_SHARP_PATH||'sharp');
const root=path.resolve(__dirname,'..'),input=path.join(root,'tmp/two-emulator-qa-2026-10-29'),out=path.join(root,'docs/theme-visual-audit/daily-qa-2026-10-29');
const progress=JSON.parse(fs.readFileSync(path.join(input,'current-progress.json'),'utf8'));
const names={dark:'Zelena',light:'Svetlo zlato',medium:'Trula višnja',winter:'Plavi okean',neon:'Neon Cyber',amethyst:'Kraljevski ametist',easter:'Vaskršnja',desert:'Pustinjsko staklo',moon:'Mesečev sjaj',severna:'Severna maglina'};
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
async function main(){
 assert.equal(Object.keys(progress.daily).length,10);fs.mkdirSync(out,{recursive:true});
 const rows=[];
 for(const [theme,name]of Object.entries(names)){
  const state=progress.daily[theme];assert.equal(state.reward,(6+6+2+5)*3*1);assert.equal(state.claim,false);
  for(const kind of ['active','complete']){const source=state[kind];assert(fs.existsSync(path.join(input,'screens',source)),source);await sharp(path.join(input,'screens',source)).resize({width:540}).jpeg({quality:88,chromaSubsampling:'4:4:4'}).toFile(path.join(out,theme+'-'+kind+'.jpg'));}
  rows.push({theme,name,...state,status:'Aktivni i završni Android panel pregledani; bez nove potrebe za PNG zamenom u tim stanjima.',geometry:'Green raspored i zajednička tipografija; tematske površine/ikone/kontrast. Panel staje iznad navigacije, bez skrola.'});
 }
 const report={date:'2026-10-29',testedCommit:progress.commit,testedGameVersion:'6.36',environment:'Isključivo com.yamb.balkan.staging / yamb-reconnect-qa / odvojeni Firebase i yamb_reconnect_qa. Javna verzija odgovara lokalnom commitu nakon normalizacije CRLF/LF.',devices:'Dva emulatora pokrenuta/prijavljena. Daily pregled svih10tema na prvom; Green ranije1440x3120/560dpi, zatim proporcionalnih720x1560/280dpi, isti logički viewport ~411x891. Nije fizički S25.',testData:'Na oba proverena QA profila dodat isključivo inventar tema za pregled, uz snapshot prethodnog stanja. Nekoliko početnih activeTheme/activeSkin QA postavki evidentirano; sačuvani klijentski izbor ih može nadjačati, pa je većina izbora stvarno obavljena u meniju. Nema resetovanja Daily pokušaja, izmene rezultata ili salda radi pregleda.',daily:'Isti nepreuzeti dnevni izazov legitimno ponovo otvoren nakon restartovanja QA aplikacije. Svih10tema: šest native STOP pritisaka, serverove kockice6/6/2/5/3/1 i rezultat57. Bez reklame, klika naPreuzmi ili potvrde isplate.',inventory:'Raniji statički popis:6semantičkih PNGuloga po temi; dukat/video kanonski, skinovi deljeni. Ovaj prolaz ne stvara nove PNGcrteže i ne menja njihove putanje.',skinException:'Plavi okean pregledan sa namerno dozvoljenim univerzalnim skinom Trule višnje. Ostale kasnije teme sa svojim skinovima; time se ne tvrdi Android dekodiranje svih mogućih48skinova u Daily sobi.',observations:progress.issues,remaining:['Nagradna reklama/uvećanje/isplata i njene greške nisu testirane. QA oglasi su blokirani, pa je dupliranje sivo i ne predstavlja kvar produkcionog oglasa.','Na emulatoru nije ponovljen svaki mali/srednji/veliki fizički uređaj. Raniji150izolovanih renderer slučajeva ostaje dopunski dokaz, ne zamena za Android.','Hladna promena tema ostaje nalaz: prviLight iMedium pokušaji ostavili prethodnu temu, ponovljeni uspeli. Nije dokazano trenutno učitavanje niti precizno trajanje intra.','Daily nema standardni vidljivi izlaz sa završetka bez preuzimanja. Radi ovog nepodizanja nagrade korišćen je restart QA aplikacije; povratak preko dugmetaPreuzmi nije ovim potvrđen.'],results:rows};
 fs.writeFileSync(path.join(out,'report.json'),JSON.stringify(report,null,2)+'\n');
 fs.writeFileSync(path.join(out,'index.html'),`<!doctype html><html lang="sr"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Daily QA — svih10tema</title><style>body{margin:0;padding:24px;background:#13232e;color:#edf6fc;font:16px/1.5 system-ui}main{max-width:1300px;margin:auto}a{color:#afe4ff}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:16px}img{width:100%;height:auto}article{background:#233847;padding:12px;border:1px solid #7895a8;border-radius:12px}</style><main><h1>Dnevni izazov — stvarni QA pregled10/10tema</h1><p>${esc(report.environment)}</p><p>${esc(report.daily)}</p><p>${esc(report.devices)}</p><a href="report.json">Precizan obuhvat i granice</a><ul>${report.remaining.map(s=>'<li>'+esc(s)+'</li>').join('')}</ul>${rows.map(r=>`<h2>${esc(r.name)}</h2><div class="grid">${['active','complete'].map(k=>`<article><h3>${k==='active'?'Aktivni panel':'Završni panel —57'}</h3><img loading="lazy" src="${r.theme}-${k}.jpg" alt="${esc(r.name)} ${k}"></article>`).join('')}</div>`).join('')}</main></html>`);
 console.log('WROTE Daily QA:10themes,20Android frames,57/no claim; ads/payout remain separate.');
}
main().catch(e=>{console.error(e);process.exitCode=1;});
